result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/aging.py", "content": """"Accounts receivable aging report.

Ingests invoices and payments (applied to invoices), computes open balances
in integer cents, and groups receivables into aging buckets by invoice age.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date, datetime


class OverpaymentError(ValueError):
    """Raised when payments applied to an invoice exceed its amount."""


BUCKETS = ("0-30", "31-60", "61-90", "90+")


def to_cents(amount: float | int | str) -> int:
    """Convert a dollar amount to integer cents without float drift."""
    if isinstance(amount, str):
        amount = float(amount.replace(",", "").replace("$", ""))
    return int(round(float(amount) * 100))


def parse_date(value: str | date) -> date:
    if isinstance(value, date):
        return value
    return date.fromisoformat(value)


@dataclass(frozen=True)
class Invoice:
    id: str
    customer: str
    date: date
    amount: int  # cents

    @classmethod
    def make(cls, id: str, customer: str, date: str | date, amount) -> "Invoice":
        return cls(id, customer, parse_date(date), to_cents(amount))

    @property
    def dollars(self) -> float:
        return self.amount / 100


@dataclass(frozen=True)
class Payment:
    invoice_id: str
    date: date
    amount: int  # cents

    @classmethod
    def make(cls, invoice_id: str, date: str | date, amount) -> "Payment":
        return cls(invoice_id, parse_date(date), to_cents(amount))


@dataclass
class Ledger:
    invoices: list[Invoice] = field(default_factory=list)
    payments: list[Payment] = field(default_factory=list)

    def add_invoice(self, invoice: Invoice) -> None:
        self.invoices.append(invoice)

    def add_payment(self, payment: Payment) -> None:
        if not any(inv.id == payment.invoice_id for inv in self.invoices):
            raise ValueError(f"payment references unknown invoice {payment.invoice_id!r}")
        self.payments.append(payment)
        # Validate immediately: total payments must never exceed the invoice.
        self._check_overpayment(self.open_balances())

    def _check_overpayment(self, balances: dict[str, int]) -> None:
        for inv_id, bal in balances.items():
            if bal < 0:
                raise OverpaymentError(
                    f"overpayment on invoice {inv_id!r}: "
                    f"payments exceed amount by ${-bal / 100:.2f}"
                )

    def open_balances(self) -> dict[str, int]:
        """Invoice id -> open balance in cents (amount minus applied payments)."""
        totals = {inv.id: inv.amount for inv in self.invoices}
        for p in self.payments:
            totals[p.invoice_id] -= p.amount
        return totals

    def bucket(self, as_of: str | date) -> dict[str, int]:
        """Group open balances by invoice age (in days) at `as_of`.

        Returns {"0-30": c, "31-60": c, "61-90": c, "90+": c} plus
        "total" under key "total".
        """
        as_of = parse_date(as_of)
        result = dict.fromkeys(BUCKETS, 0)
        balances = self.open_balances()
        for inv in self.invoices:
            balance = balances[inv.id]
            if balance == 0:
                continue
            age_days = (as_of - inv.date).days
            if age_days <= 30:
                key = "0-30"
            elif age_days <= 60:
                key = "31-60"
            elif age_days <= 90:
                key = "61-90"
            else:
                key = "90+"
            result[key] += balance
        result["total"] = sum(result[b] for b in BUCKETS)
        return result

    def by_customer(self, as_of: str | date) -> dict[str, dict[str, int]]:
        """customer -> bucket -> cents, per-customer subtotals."""
        as_of = parse_date(as_of)
        report: dict[str, dict[str, int]] = {}
        balances = self.open_balances()
        for inv in self.invoices:
            balance = balances[inv.id]
            if balance == 0:
                continue
            cust = report.setdefault(
                inv.customer, dict.fromkeys(BUCKETS + ("total",), 0)
            )
            age_days = (as_of - inv.date).days
            if age_days <= 30:
                key = "0-30"
            elif age_days <= 60:
                key = "31-60"
            elif age_days <= 90:
                key = "61-90"
            else:
                key = "90+"
            cust[key] += balance
            cust["total"] += balance
        return report

    def render(self, as_of: str | date) -> str:
        """Aligned text table of the aging report."""
        as_of = parse_date(as_of)
        buckets = self.bucket(as_of)
        customers = self.by_customer(as_of)

        headers = ("Customer", *BUCKETS, "Total")
        rows: list[tuple[str, ...]] = [headers]

        def fmt(cents: int) -> str:
            sign = "-" if cents < 0 else ""
            return f"{sign}{abs(cents) // 100:,}.{abs(cents) % 100:02d}"

        for customer in sorted(customers):
            c = customers[customer]
            rows.append((customer, *(fmt(c[b]) for b in BUCKETS), fmt(c["total"])))
        rows.append(("TOTAL", *(fmt(buckets[b]) for b in BUCKETS), fmt(buckets["total"])))

        widths = [
            max(len(r[i]) for r in rows) for i in range(len(headers))
        ]
        lines = []
        sep = "+".join("-" * (w + 2) for w in widths)
        lines.append(sep)
        for i, row in enumerate(rows):
            line = "| " + " | ".join(
                cell.ljust(widths[j]) if j == 0 else cell.rjust(widths[j])
                for j, cell in enumerate(row)
            ) + " |"
            lines.append(line)
            if i in (0, len(rows) - 2):
                lines.append(sep)
        lines.insert(0, f"Accounts Receivable Aging — as of {as_of.isoformat()}")
        return "\n".join(lines)


def fixture() -> Ledger:
    ledger = Ledger()
    ledger.add_invoice(Invoice.make("INV-001", "Acme Corp",   "2026-03-15", 1000.00))
    ledger.add_invoice(Invoice.make("INV-002", "Globex Ltd",  "2026-02-20", 500.00))
    ledger.add_invoice(Invoice.make("INV-003", "Initech",     "2026-01-10", 750.00))
    ledger.add_invoice(Invoice.make("INV-004", "Umbrella Co", "2025-11-30", 2400.00))
    ledger.add_payment(Payment.make("INV-002", "2026-03-05", 200.00))
    ledger.add_payment(Payment.make("INV-003", "2026-02-01", 750.00))
    ledger.add_payment(Payment.make("INV-004", "2026-01-15", 400.00))
    return ledger


def main(argv: list[str] | None = None) -> None:
    argv = argv if argv is not None else []
    as_of = argv[0] if argv else "2026-03-31"
    print(fixture().render(as_of))


if __name__ == "__main__":
    main()
